import React, { useState, useEffect } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import { Chart, registerables } from "chart.js";
Chart.register(...registerables);

function App() {
  const [ads, setAds] = useState([]);
  const [strategy, setStrategy] = useState("thompson");
  const [metrics, setMetrics] = useState({});
  const [selectedAd, setSelectedAd] = useState(null);

  // Fetch ads and strategies on mount
  useEffect(() => {
    axios.get("http://localhost:5000/api/ads")
      .then((res) => setAds(res.data.ads))
      .catch((err) => console.error("Error fetching ads:", err));
  }, []);

  // Fetch metrics every 5 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      axios.get(`http://localhost:5000/api/metrics/${strategy}`)
        .then((res) => setMetrics(res.data))
        .catch((err) => console.error("Error fetching metrics:", err));
    }, 1000);
    return () => clearInterval(interval);
  }, [strategy]);

  // Simulate ad click
  const handleAdClick = async (adIndex) => {
    try {
      const response = await axios.post("http://localhost:5000/api/click_ad", {
        strategy: strategy,
        ad_index: adIndex,
      });
      setSelectedAd(response.data);
    } catch (err) {
      console.error("Error clicking ad:", err);
    }
  };

  // Chart data for CTR and rewards
  const chartData = {
    labels: metrics.timestamps || [],
    datasets: [
      {
        label: "CTR (%)",
        data: metrics.ctr ? metrics.ctr.map(v => v * 100) : [],
        borderColor: "rgb(75, 192, 192)",
        tension: 0.1,
      },
      {
        label: "Average Reward",
        data: metrics.avg_reward || [],
        borderColor: "rgb(255, 99, 132)",
        tension: 0.1,
      },
    ],
  };

  return (
    <div style={{ padding: "20px", maxWidth: "800px", margin: "0 auto" }}>
      <h1>Online Advertising Simulation (A/B Testing)</h1>

      {/* Strategy selector */}
      <div style={{ margin: "20px 0" }}>
        <label>Strategy: </label>
        <select value={strategy} onChange={(e) => setStrategy(e.target.value)}>
          <option value="thompson">Thompson Sampling</option>
          <option value="random">Random Selection</option>
        </select>
      </div>

      {/* Ad buttons */}
      <div style={{ display: "flex", gap: "10px", marginBottom: "20px" }}>
        {ads.map((ad) => (
          <button
            key={ad}
            onClick={() => handleAdClick(ad)}
            style={{ padding: "10px", cursor: "pointer" }}
          >
            Ad {ad + 1}
          </button>
        ))}
      </div>

      {/* Performance metrics */}
      {selectedAd && (
        <div style={{ marginBottom: "20px" }}>
          <h3>Last Interaction (Strategy: {strategy})</h3>
          <p>Ad {selectedAd.ad_id}: Clicked? {selectedAd.click ? "Yes" : "No"}</p>
          <p>Reward: {selectedAd.reward.toFixed(2)}</p>
        </div>
      )}

      {/* Historical metrics chart */}
      <div style={{ marginTop: "40px" }}>
        <h2>Performance Over Time</h2>
        <Line data={chartData} options={{ responsive: true }} />
      </div>
    </div>
  );
}

export default App;
